//! ERP WebSocket subscription SQL (org-scoped rows from `erp-org-sql.json`, generated by `make codegen`).

use std::collections::HashMap;

use once_cell::sync::Lazy;
use serde::Deserialize;

use crate::field_policy::{
    company_ids_dual_field_or_clause, company_ids_equality_or_clause,
    resolve_http_sql_columns, select_field_permissions_for_org_sql, select_org_scoped_sql,
    select_roles_active_sql, select_user_role_assignments_for_identity_sql,
    sql_column_list_for_generated_type, FieldAccessContext,
};

#[derive(Debug, Clone, Default)]
pub struct SubscriptionQueryContext<'a> {
    pub organization_id: Option<u64>,
    pub company_ids: Option<&'a [u64]>,
    pub identity_hex: Option<&'a str>,
    pub role_names: Option<&'a [String]>,
    /// Manager's `hr_employee.id` for `direct-reports` (no SQL subqueries).
    pub manager_employee_id: Option<u64>,
    pub field_access: Option<&'a FieldAccessContext>,
}

#[derive(Debug, Deserialize)]
struct ErpOrgRow {
    /// Emitted as camelCase `mapKey` by `lumiere-codegen` erp_org_sql_emit.
    #[serde(rename = "mapKey")]
    map_key: String,
    resource_key: String,
    table: String,
    extra_where: String,
    order_by: String,
}

static ERP_ORG_ROWS: Lazy<Vec<ErpOrgRow>> = Lazy::new(|| {
    serde_json::from_str(include_str!("../assets/erp-org-sql.json")).expect("erp-org-sql.json")
});

static ERP_ORG_INDEX: Lazy<HashMap<String, usize>> = Lazy::new(|| {
    ERP_ORG_ROWS
        .iter()
        .enumerate()
        .map(|(i, r)| (r.map_key.clone(), i))
        .collect()
});

fn auth_select_all(table: &str, type_name: &str) -> Result<String, String> {
    let cols = sql_column_list_for_generated_type(type_name)?.join(", ");
    Ok(format!("SELECT {cols} FROM {table}"))
}

static AUTH_SINGLE: Lazy<HashMap<String, String>> = Lazy::new(|| {
    let mut m = HashMap::new();
    m.insert(
        "user-profile".into(),
        auth_select_all("user_profile", "UserProfile").expect("UserProfile cols"),
    );
    m.insert(
        "user-role-assignment".into(),
        auth_select_all("user_role_assignment", "UserRoleAssignment")
            .expect("UserRoleAssignment cols"),
    );
    m.insert(
        "auth-role-table".into(),
        auth_select_all("role", "Role").expect("Role cols"),
    );
    m.insert(
        "user-organization".into(),
        auth_select_all("user_organization", "UserOrganization").expect("UserOrganization cols"),
    );
    m
});

fn sql_quote_str(s: &str) -> String {
    format!("'{}'", s.replace('\'', "''"))
}

fn is_narrow_identity_hex(s: &str) -> bool {
    let s = s.trim();
    s.len() == 64 && s.chars().all(|c| c.is_ascii_hexdigit())
}

/// Port of `authSubscriptions` from `queries/auth.ts` (uses `SELECT *`).
pub fn auth_subscriptions(
    identity_hex: Option<&str>,
    role_names: Option<&[String]>,
    organization_id: Option<u64>,
) -> Vec<String> {
    let id = identity_hex
        .map(str::trim)
        .filter(|s| is_narrow_identity_hex(s))
        .map(|s| s.to_ascii_lowercase());

    let roles: Vec<&str> = role_names
        .map(|v| {
            v.iter()
                .map(|s| s.as_str())
                .filter(|r| !r.is_empty() && r.len() < 256)
                .collect()
        })
        .unwrap_or_default();

    let user_profile_sql = if let Some(ref hex) = id {
        format!("SELECT * FROM user_profile WHERE identity = 0x{hex}")
    } else {
        "SELECT * FROM user_profile".into()
    };

    let user_role_assignment_sql = if let Some(ref hex) = id {
        format!(
            "SELECT * FROM user_role_assignment WHERE user_identity = 0x{hex} AND is_active = true"
        )
    } else {
        "SELECT * FROM user_role_assignment".into()
    };

    let org_id_num = organization_id.filter(|&n| n > 0);

    let role_sql = if let Some(n) = org_id_num {
        format!("SELECT * FROM role WHERE organization_id = {n}")
    } else {
        "SELECT * FROM role".into()
    };

    let user_organization_sql = if let Some(ref hex) = id {
        format!(
            "SELECT * FROM user_organization WHERE user_identity = 0x{hex} AND is_active = true"
        )
    } else {
        "SELECT * FROM user_organization".into()
    };

    let field_permission_sql = if let Some(n) = org_id_num {
        select_field_permissions_for_org_sql(n).expect("field permission sql")
    } else {
        "SELECT id, organization_id, subject, role_id, resource, action, allowed_fields, created_by, created_at FROM field_permission".into()
    };

    vec![
        user_profile_sql,
        user_role_assignment_sql,
        role_sql,
        user_organization_sql,
        field_permission_sql,
    ]
}

enum CompanyScoped {
    NotApplicable,
    MissingContext,
    Queries(Vec<String>),
}

fn subscription_sql_for_company_scoped(
    resource: &str,
    ctx: &SubscriptionQueryContext<'_>,
) -> Result<CompanyScoped, String> {
    let fa = ctx.field_access;
    let ids = ctx.company_ids.filter(|v| !v.is_empty());

    match resource {
        "fixed-assets" => {
            let Some(list_ids) = ids else {
                return Ok(CompanyScoped::MissingContext);
            };
            let c = resolve_http_sql_columns("fixed-assets", fa)?.join(", ");
            let filter = company_ids_equality_or_clause("company_id", list_ids)?;
            Ok(CompanyScoped::Queries(vec![format!(
                "SELECT {c} FROM account_asset WHERE {filter}"
            )]))
        }
        "intercompany-rules" => {
            let Some(list_ids) = ids else {
                return Ok(CompanyScoped::MissingContext);
            };
            let c = resolve_http_sql_columns("intercompany-rules", fa)?.join(", ");
            let filter =
                company_ids_dual_field_or_clause("source_company_id", "destination_company_id", list_ids)?;
            Ok(CompanyScoped::Queries(vec![format!(
                "SELECT {c} FROM intercompany_rule WHERE {filter} ORDER BY sequence ASC"
            )]))
        }
        "intercompany-transactions" => {
            let Some(list_ids) = ids else {
                return Ok(CompanyScoped::MissingContext);
            };
            let c = resolve_http_sql_columns("intercompany-transactions", fa)?.join(", ");
            let filter =
                company_ids_dual_field_or_clause("origin_company_id", "destination_company_id", list_ids)?;
            Ok(CompanyScoped::Queries(vec![format!(
                "SELECT {c} FROM intercompany_transaction WHERE {filter} ORDER BY id DESC"
            )]))
        }
        "pos-configs" => {
            let Some(list_ids) = ids else {
                return Ok(CompanyScoped::MissingContext);
            };
            let c = resolve_http_sql_columns("pos-configs", fa)?.join(", ");
            let filter = company_ids_equality_or_clause("company_id", list_ids)?;
            Ok(CompanyScoped::Queries(vec![format!(
                "SELECT {c} FROM pos_config WHERE {filter} ORDER BY name ASC"
            )]))
        }
        "picking-batches" => {
            let Some(list_ids) = ids else {
                return Ok(CompanyScoped::MissingContext);
            };
            let c = resolve_http_sql_columns("picking-batches", fa)?.join(", ");
            let filter = company_ids_equality_or_clause("company_id", list_ids)?;
            Ok(CompanyScoped::Queries(vec![format!(
                "SELECT {c} FROM stock_picking_batch WHERE {filter}"
            )]))
        }
        "depreciation-lines" => Ok(CompanyScoped::MissingContext),
        _ => Ok(CompanyScoped::NotApplicable),
    }
}

fn erp_org_line(
    resource: &str,
    org: u64,
    fa: Option<&FieldAccessContext>,
) -> Result<Option<String>, String> {
    let Some(&idx) = ERP_ORG_INDEX.get(resource) else {
        return Ok(None);
    };
    let ent = &ERP_ORG_ROWS[idx];
    Ok(Some(select_org_scoped_sql(
        &ent.resource_key,
        &ent.table,
        org,
        fa,
        &ent.extra_where,
        &ent.order_by,
    )?))
}

/// `extra_where` clause from `erp-org-sql.json` for a map key (includes leading ` AND …`).
/// Used by HTTP `query_exec` so bounded exception resources match WebSocket SQL.
pub fn erp_org_extra_where(resource: &str) -> Option<&'static str> {
    let idx = *ERP_ORG_INDEX.get(resource)?;
    let extra = ERP_ORG_ROWS[idx].extra_where.as_str();
    if extra.is_empty() {
        None
    } else {
        Some(extra)
    }
}

/// `Ok(None)` when the resource is unknown or required context is missing.
pub fn subscription_queries_for_resource(
    resource: &str,
    ctx: &SubscriptionQueryContext<'_>,
) -> Result<Option<Vec<String>>, String> {
    let r = resource.trim();
    if r.is_empty() {
        return Ok(None);
    }

    if r == "auth" {
        return Ok(Some(auth_subscriptions(
            ctx.identity_hex,
            ctx.role_names,
            ctx.organization_id,
        )));
    }

    if let Some(sql) = AUTH_SINGLE.get(r) {
        return Ok(Some(vec![sql.clone()]));
    }

    if r == "roles" {
        return Ok(Some(vec![select_roles_active_sql(ctx.field_access)?]));
    }

    if r == "form-configuration" {
        let Some(org) = ctx.organization_id else {
            return Ok(None);
        };
        let fc = sql_column_list_for_generated_type("FormConfig")?.join(", ");
        let ucf = sql_column_list_for_generated_type("UserCustomField")?.join(", ");
        return Ok(Some(vec![
            format!("SELECT {fc} FROM form_config WHERE organization_id = {org}"),
            format!("SELECT {ucf} FROM user_custom_field WHERE organization_id = {org}"),
        ]));
    }

    if r == "user-roles" {
        let Some(id) = ctx.identity_hex.filter(|s| *s != "unknown") else {
            return Ok(None);
        };
        return Ok(Some(vec![select_user_role_assignments_for_identity_sql(
            id,
            ctx.field_access,
        )?]));
    }

    if r == "my-employee" {
        let Some(org) = ctx.organization_id else {
            return Ok(None);
        };
        let Some(id) = ctx.identity_hex.filter(|s| *s != "unknown") else {
            return Ok(None);
        };
        let id_lit = crate::field_policy::identity_sql_literal(id)?;
        let cols = resolve_http_sql_columns("my-employee", ctx.field_access)?.join(", ");
        return Ok(Some(vec![format!(
            "SELECT {cols} FROM hr_employee WHERE organization_id = {org} AND user_id = {id_lit} AND is_active = true"
        )]));
    }

    if r == "direct-reports" {
        let Some(org) = ctx.organization_id else {
            return Ok(None);
        };
        let Some(manager_id) = ctx.manager_employee_id.filter(|&id| id > 0) else {
            return Ok(None);
        };
        let cols = resolve_http_sql_columns("direct-reports", ctx.field_access)?.join(", ");
        return Ok(Some(vec![format!(
            "SELECT {cols} FROM hr_employee WHERE organization_id = {org} AND parent_id = {manager_id} AND is_active = true"
        )]));
    }

    if r == "employee-documents" {
        let Some(org) = ctx.organization_id else {
            return Ok(None);
        };
        let cols = resolve_http_sql_columns("employee-documents", ctx.field_access)?.join(", ");
        let mut extra = String::from(" AND active = true");
        if !crate::field_policy::has_hr_permission(ctx.field_access, "hr_employee", "view_pii") {
            extra.push_str(" AND purpose NOT IN ('tax_id', 'identity')");
        }
        return Ok(Some(vec![format!(
            "SELECT {cols} FROM hr_employee_document WHERE organization_id = {org}{extra}"
        )]));
    }

    // Document folder ACL: HTTP SQL cannot express Vec<Identity> membership
    // (`read_access_ids`). Honest subset = unrestricted OR caller is owner.
    if r == "document-folders" {
        let Some(org) = ctx.organization_id else {
            return Ok(None);
        };
        let Some(id) = ctx.identity_hex.filter(|s| *s != "unknown") else {
            return Ok(None);
        };
        let id_lit = crate::field_policy::identity_sql_literal(id)?;
        let cols = resolve_http_sql_columns("document-folders", ctx.field_access)?.join(", ");
        return Ok(Some(vec![format!(
            "SELECT {cols} FROM doc_folder WHERE organization_id = {org} AND (is_access_restricted = false OR owner_id = {id_lit})"
        )]));
    }

    if r == "documents" || r == "documents-deleted" {
        let Some(org) = ctx.organization_id else {
            return Ok(None);
        };
        let Some(id) = ctx.identity_hex.filter(|s| *s != "unknown") else {
            return Ok(None);
        };
        let id_lit = crate::field_policy::identity_sql_literal(id)?;
        let cols = resolve_http_sql_columns(r, ctx.field_access)?.join(", ");
        let deleted = if r == "documents-deleted" {
            "true"
        } else {
            "false"
        };
        return Ok(Some(vec![format!(
            "SELECT {cols} FROM document WHERE organization_id = {org} AND is_deleted = {deleted} AND owner_id = {id_lit}"
        )]));
    }

    if r == "field-permissions" {
        let Some(org) = ctx.organization_id else {
            return Ok(None);
        };
        return Ok(Some(vec![select_field_permissions_for_org_sql(org)?]));
    }

    let Some(org) = ctx.organization_id else {
        return Ok(None);
    };

    match subscription_sql_for_company_scoped(r, ctx)? {
        CompanyScoped::NotApplicable => {}
        CompanyScoped::MissingContext => return Ok(None),
        CompanyScoped::Queries(q) => return Ok(Some(q)),
    }

    let Some(line) = erp_org_line(r, org, ctx.field_access)? else {
        return Ok(None);
    };
    Ok(Some(vec![line]))
}

pub fn create_client_subscriptions<T: AsRef<str>>(
    resources: &[T],
    ctx: &SubscriptionQueryContext<'_>,
) -> Result<Vec<String>, String> {
    let identity_hex = ctx.identity_hex.filter(|s| *s != "unknown");
    let scoped = SubscriptionQueryContext {
        organization_id: ctx.organization_id,
        company_ids: ctx.company_ids,
        identity_hex,
        role_names: ctx.role_names,
        manager_employee_id: ctx.manager_employee_id,
        field_access: ctx.field_access,
    };

    let mut out = Vec::new();
    for key in resources {
        let key = key.as_ref();
        if let Some(part) = subscription_queries_for_resource(key, &scoped)? {
            out.extend(part);
        }
    }
    Ok(out)
}

pub static SUBSCRIPTION_RESOURCE_KEYS_JSON: &str =
    include_str!("../assets/subscription-resource-keys.json");

pub static FULL_CLIENT_SUBSCRIPTION_RESOURCES_JSON: &str =
    include_str!("../assets/full-client-subscription-resources.json");

pub fn subscription_resource_keys_vec() -> Vec<String> {
    serde_json::from_str(SUBSCRIPTION_RESOURCE_KEYS_JSON).expect("subscription-resource-keys.json")
}

pub fn full_client_subscription_resources_vec() -> Vec<String> {
    serde_json::from_str(FULL_CLIENT_SUBSCRIPTION_RESOURCES_JSON)
        .expect("full-client-subscription-resources.json")
}
